(function(){"use strict";const s=self;s.onmessage=async e=>{const{id:r,blob:a}=e.data||{};try{if(!(self.crypto&&crypto.subtle)){s.postMessage({id:r,hex:null});return}const t=await crypto.subtle.digest("SHA-256",await a.arrayBuffer()),o=Array.from(new Uint8Array(t),n=>n.toString(16).padStart(2,"0")).join("");s.postMessage({id:r,hex:o})}catch(t){s.postMessage({id:r,error:String(t instanceof Error&&t.message||t)})}}})();
